import{_ as o,o as t,c,a4 as d}from"./chunks/framework.kn7HWrZO.js";const u=JSON.parse('{"title":"在反向代理之后发布 Web UI","description":"","frontmatter":{"editSource":"docs/user/guide/public-deployments.zh.md","rawMarkdownPath":"guide/public-deployments.md"},"headers":[],"relativePath":"guide/public-deployments.md","filePath":"guide/public-deployments.md"}'),i={name:"guide/public-deployments.md"};function a(s,e,r,l,p,n){return t(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="在反向代理之后发布-web-ui" tabindex="-1">在反向代理之后发布 Web UI <a class="header-anchor" href="#在反向代理之后发布-web-ui" aria-label="Permalink to &quot;在反向代理之后发布 Web UI&quot;">​</a></h1><p><code>dsh --profile web</code> 在 loopback 端口上提供 GUI，因此其他机器上的浏览器无法访问它，进程也无从得知你实际使用的地址。它前面的反向代理拥有这条外部链路——公开主机名、TLS，以及转发到监听器之前剥离的路径前缀——<code>--public-url</code> 则告诉 DSH 浏览器使用的是哪个地址：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --public-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://app.example/ui/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trusted-host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.example</span></span></code></pre></div><h2 id="public-url-公告什么" tabindex="-1"><code>--public-url</code> 公告什么 <a class="header-anchor" href="#public-url-公告什么" aria-label="Permalink to &quot;`--public-url` 公告什么&quot;">​</a></h2><p><code>--public-url</code> 接受可带挂载前缀的 <code>http://</code> 或 <code>https://</code> 根，并把它归一化为以 <code>/</code> 结尾。它提供打印与打开的启动 URL、<code>DSH_WEB_URL</code>，以及 agent 运行时上下文中的 Web GUI URL。webserver 继续提供 origin-root 路由，且从不了解挂载。<code>publicUrl</code> 配置字段发布同样的公告。</p><h2 id="代理必须做什么" tabindex="-1">代理必须做什么 <a class="header-anchor" href="#代理必须做什么" aria-label="Permalink to &quot;代理必须做什么&quot;">​</a></h2><ul><li><strong>保留浏览器可见的 <code>Host</code>。</strong> 栅栏把收到的 <code>Host</code> 与被接受的 authority 比对，因此代理应原样转发，而不要改写成监听器的地址。</li><li><strong>剥离挂载前缀。</strong> 监听器应答的是 origin-root 路由，因此对 <code>/ui/api/...</code> 的请求必须以 <code>/api/...</code> 抵达。</li><li><strong>转发升级请求。</strong> 页面发出的每个请求与 WebSocket 升级都必须连同其 <code>Upgrade</code> 与 <code>Connection</code> 头抵达监听器；代理对外提供 HTTPS 时，TLS 在其外部链路上终止。</li><li><strong>改写 cookie 作用域。</strong> 以明文 HTTP 提供服务的后端签发不带 <code>Secure</code> 的 host-only <code>Path=/</code> cookie；代理再把 <code>Path</code> 改写为挂载（<code>/ui/</code>），并仅在其 HTTPS 链路上添加 <code>Secure</code>。监听器自身提供 TLS 时 cookie 已带 <code>Secure</code>，代理只需改写 <code>Path</code>。</li><li><strong>重定向裸挂载。</strong> <code>/ui/</code> 是唯一入口：只有它把启动 token 换成会话 cookie；已持有该 cookie 的浏览器可由它或 <code>/ui/index.html</code> 取得文档，因为所提供的文档以自身目录解析 URL。对 <code>/ui</code> 的请求必须以 <code>/ui/</code> 抵达，而被剥离路径的后端无法重建该外部路径。</li></ul><h2 id="信任浏览器使用的-authority" tabindex="-1">信任浏览器使用的 authority <a class="header-anchor" href="#信任浏览器使用的-authority" aria-label="Permalink to &quot;信任浏览器使用的 authority&quot;">​</a></h2><p>栅栏接受 loopback、监听器自身的绑定地址，以及每个由 <code>--trusted-host</code> 点名的 authority。浏览器若以其他任何 authority 访问部署，无论代理多么正确，每个 API 调用都会得到 403，因此请用 <code>--trusted-host</code> 点名浏览器可见的 authority；用 <code>--public-url</code> 公告它只是展示，并不等于接纳。不带端口的条目匹配任意端口，适合每次绑定不同端口的隧道。栅栏只放行请求；打印 URL 中的启动 token 与签名会话 cookie 才完成认证。无论 TLS 在哪里终止都不改变这一切：证书只是向浏览器标识服务器，而不是向服务器标识浏览器。</p><p>无论是公告 URL 还是栅栏都不保护监听端口本身，因此请把端口限制在可信代理或网络内。</p><h2 id="保护外部链路" tabindex="-1">保护外部链路 <a class="header-anchor" href="#保护外部链路" aria-label="Permalink to &quot;保护外部链路&quot;">​</a></h2><p>可以在代理处、监听器本身或两者上终止 TLS；<code>--public-url</code> 仍只是公告。面向浏览器的 <code>http://</code> 根会明文暴露启动 token。<code>https://</code> 代理根保护浏览器到代理这一段；代理与监听器之间是否加密取决于监听器的 TLS 配置。</p><p>要在监听器上终止 TLS，请传入 <code>--tls-cert</code> 与 <code>--tls-key</code>，两者各是相对进程工作目录解析的路径：证书文件包含完整证书链，密钥文件为不带口令的 PEM 私钥。DSH 从不获取、续期或监视证书，且载体只读取一次文件，因此更换文件后需重新加载监听器或重启进程；文件缺失或无效时启动失败，绝不回退到 HTTP。浏览器使用自己的信任库与名称校验，因此证书必须覆盖你所访问的 hostname 或 IP。默认端口仍为 3080。原生 TLS 不需要代理，但代理部署与 <code>--public-url</code> 仍分别受支持。TLS 监听器会给会话 cookie 加上 <code>Secure</code>；公开部署的浏览器侧链路应保持 HTTPS，才能让浏览器回传这些 cookie。</p><p>打印的 URL 携带进程凭据，只应与预期用户分享。</p><p><a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/web-app/README.zh.md#public-deployments" target="_blank" rel="noreferrer">Web 应用参考</a>说明 <code>--public-url</code>、<code>--trusted-host</code> 与 <code>--tls-cert</code>/<code>--tls-key</code> 命令行选项。在 Web profile 中，<code>publicUrl</code> 配置在 <code>web-runtime</code> 行，<code>trustedHosts</code> 配置在 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/client/connection/README.zh.md" target="_blank" rel="noreferrer">Connection 行</a>，<code>tls</code> 配置在 <a href="./../reference/subsystems/web-server#config">webserver 行</a>。</p>',15)])])}const b=o(i,[["render",a]]);export{u as __pageData,b as default};
